SELECT ListeInterventionGenerale.nomzon,ListeInterventionGenerale.nomcli,ListeInterventionGenerale.numsit,ListeInterventionGenerale.codsit,ListeInterventionGenerale.nomsit,ListeInterventionGenerale.adrsit,ListeInterventionGenerale.codpossit,ListeInterventionGenerale.vilsit,ListeInterventionGenerale.telsit,IIf([typint]="1","ENTRETIEN",IIf([typint]="2","DEPANNAGE",IIf([typint]="3","TRAVAUX SELON DEVIS",IIf([typint]="7","DESENFUMAGE","AUTRES")))),ListeInterventionGenerale.numdevacc,ListeInterventionGenerale.refcliint,IIf([staint]=-1,"Matériel en attente",IIf([staint]=1,"A planifier",IIf([staint]=5,"En cours",IIf([staint]=6,"Effectuée en attente retour fiche intervention",IIf([staint]=7,"Clôturée",IIf([staint]=8,"Annulée avec accord client",IIf([staint]=9,"Réalisée - à valider"))))))),ListeInterventionGenerale.datheulim,ListeInterventionGenerale.datintpre,ListeInterventionGenerale.datint,ListeInterventionGenerale.numintint,ListeInterventionGenerale.sigsit,ListeInterventionGenerale.sigtec,ListeInterventionGenerale.NumeroDevisInterne,ListeInterventionGenerale.comtec FROM [ListeInterventionGenerale] WHERE True  and Liste.[staint]=9 
